import { GEO } from './city-geodata.js';

// js/world/city-config.js
// City spatial configuration & street database at true 1:1 scale, derived from the real geography in
// js/world/city-geodata.js (generated by tools/build-tepic-geodata.mjs from OpenStreetMap for Tepic, Nayarit): the street
// centreline graph, the curb islands (blocks), the parks, the named roads and places.
//
// World frame: 1 unit = 1 m, x = east, z = south (north = -z) on the axes of the centro's street grid (turned
// GEO.frame.bearingDeg from true north), origin at the Plaza Principal.

const toPts = (flat) => {
  const out = [];
  for (let i = 0; i < flat.length; i += 2) out.push({ x: flat[i], z: flat[i + 1] });
  return out;
};
const CITY = GEO.frame;

// The numbered streets & avenues of the New York game this was forked from. Tepic has no such grid: the lists stay
// empty for the grid-era consumers (road-network.js, city-grid.js, buildings.js), and streetZ / avenueX only remain
// as their former fallbacks for the code that still calls them (controllers.js, tsl-materials.js, buildings.js)
const ALL_AVENUES = [];
const ALL_STREETS = [];
const streetZ = (n) => (42 - n) * 79.5;
const avenueX = () => NaN;

// No Central Park in Tepic: null, which every consumer skips (still imported by controllers.js)
const CENTRAL_PARK_BOUNDS = null;

// ---------------------------------------------------------------------------------------------------------------------
// City outline: the detailed box (GEO.manhattan, its schema name from the New York game); west / east edge x at any z
// ---------------------------------------------------------------------------------------------------------------------
const CITY_OUTLINE = toPts(GEO.manhattan);
const SHORE = (() => {
  const step = 2;
  let z0 = Infinity;
  let z1 = -Infinity;
  for (const p of CITY_OUTLINE) {
    z0 = Math.min(z0, p.z);
    z1 = Math.max(z1, p.z);
  }
  z0 = Math.ceil(z0 / step) * step;
  const n = Math.floor((z1 - z0) / step) + 1;
  const west = new Float32Array(n).fill(NaN);
  const east = new Float32Array(n).fill(NaN);
  const P = CITY_OUTLINE;
  for (let i = 0, j = P.length - 1; i < P.length; j = i++) {
    const a = P[j];
    const b = P[i];
    if (a.z === b.z) continue;
    const lo = Math.min(a.z, b.z);
    const hi = Math.max(a.z, b.z);
    for (let k = Math.max(0, Math.ceil((lo - z0) / step)); k < n && z0 + k * step < hi; k++) {
      const z = z0 + k * step + 1e-3;
      if (z < lo || z >= hi) continue;
      const x = a.x + ((z - a.z) * (b.x - a.x)) / (b.z - a.z);
      if (!(west[k] <= x)) west[k] = x;
      if (!(east[k] >= x)) east[k] = x;
    }
  }
  // close any gaps (exactly horizontal runs) from the neighbours
  for (let k = 1; k < n; k++) if (Number.isNaN(west[k])) { west[k] = west[k - 1]; east[k] = east[k - 1]; }
  for (let k = n - 2; k >= 0; k--) if (Number.isNaN(west[k])) { west[k] = west[k + 1]; east[k] = east[k + 1]; }
  return { z0, step, n, west, east, z1 };
})();

/** West / east edge x of the city outline at a given z (the outermost crossings), clamped at its ends */
function getIslandBoundsAtZ(z) {
  const f = (z - SHORE.z0) / SHORE.step;
  const k = Math.max(0, Math.min(SHORE.n - 2, Math.floor(f)));
  const t = Math.max(0, Math.min(1, f - k));
  return {
    westX: SHORE.west[k] + (SHORE.west[k + 1] - SHORE.west[k]) * t,
    eastX: SHORE.east[k] + (SHORE.east[k + 1] - SHORE.east[k]) * t
  };
}

// Named roads (the real centreline, merged per street) — maps, labels & lookups
const ROADS = (GEO.roads || []).map(([name, w, dir, lanes, hw, flat]) => ({ name, raw: name, w, dir, lanes, highway: !!hw, pts: toPts(flat) }));
// Nearest-road index (labels, sidewalk tests): uniform grid of road segments
const ROAD_CELL = 64;
const ROAD_GRID = new Map();
for (const r of ROADS) {
  for (let i = 0; i + 1 < r.pts.length; i++) {
    const a = r.pts[i];
    const b = r.pts[i + 1];
    const seg = { r, ax: a.x, az: a.z, bx: b.x, bz: b.z };
    const ix0 = Math.floor(Math.min(a.x, b.x) / ROAD_CELL), ix1 = Math.floor(Math.max(a.x, b.x) / ROAD_CELL);
    const iz0 = Math.floor(Math.min(a.z, b.z) / ROAD_CELL), iz1 = Math.floor(Math.max(a.z, b.z) / ROAD_CELL);
    for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
      const k = ix * 100000 + iz;
      if (!ROAD_GRID.has(k)) ROAD_GRID.set(k, []);
      ROAD_GRID.get(k).push(seg);
    }
  }
}
/** Nearest roads to (x, z) within `radius`: [{ road, dist }] sorted by distance (one entry per road name) */
function nearestRoads(x, z, radius = 60) {
  const best = new Map();
  const ix0 = Math.floor((x - radius) / ROAD_CELL), ix1 = Math.floor((x + radius) / ROAD_CELL);
  const iz0 = Math.floor((z - radius) / ROAD_CELL), iz1 = Math.floor((z + radius) / ROAD_CELL);
  for (let ix = ix0; ix <= ix1; ix++) for (let iz = iz0; iz <= iz1; iz++) {
    const list = ROAD_GRID.get(ix * 100000 + iz);
    if (!list) continue;
    for (const s of list) {
      const dx = s.bx - s.ax, dz = s.bz - s.az;
      const L2 = dx * dx + dz * dz || 1e-9;
      const t = Math.max(0, Math.min(1, ((x - s.ax) * dx + (z - s.az) * dz) / L2));
      const d = Math.hypot(s.ax + t * dx - x, s.az + t * dz - z);
      if (d > radius) continue;
      const prev = best.get(s.r.name);
      if (!prev || d < prev.dist) best.set(s.r.name, { road: s.r, dist: d, horizontal: Math.abs(dx) > Math.abs(dz) });
    }
  }
  return [...best.values()].sort((a, b) => a.dist - b.dist);
}

// ---------------------------------------------------------------------------------------------------------------------
// Blocks: every real curb island (raised sidewalk slab) with its lot rectangles inside the property line
//   poly: curb outline [{x, z}], rects: [[x0, x1, z0, z1], ...] building lots (axis-aligned; one for a grid block),
//   park: share covered by parkland, parkName, rect: the island is an axis-aligned rectangle,
//   frames: irregular islands' lots laid out along the streets they front, [[θ, px, pz, rects], ...] (rects in a
//   frame turned by θ about (px, pz): world = p + R_y(θ)·(local − p)), or null
// ---------------------------------------------------------------------------------------------------------------------
const BLOCKS = GEO.blocks.map(([flat, rects, park, parkName, isRect, frames, rural], id) => {
  const poly = toPts(flat);
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity, a = 0, cx = 0, cz = 0;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const p = poly[i], q = poly[j];
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
    const c = q.x * p.z - p.x * q.z;
    a += c; cx += (q.x + p.x) * c; cz += (q.z + p.z) * c;
  }
  a *= 0.5;
  const area = Math.abs(a);
  return {
    // open country (fields, hills & scrub between the roads around an inland city): treated as parkland, built on by none
    id, poly, rects, frames: frames || null, park: rural ? 1 : park, parkName, rect: !!isRect, area, rural: !!rural,
    minX, maxX, minZ, maxZ,
    cx: a ? cx / (6 * a) : (minX + maxX) / 2,
    cz: a ? cz / (6 * a) : (minZ + maxZ) / 2,
    median: !rural && (/Malls?$/.test(parkName) || Math.min(maxX - minX, maxZ - minZ) < 9)
  };
});
// Spatial index of the blocks (64 m cells)
const BLOCK_CELL = 64;
const BLOCK_GRID = new Map();
for (const b of BLOCKS) {
  for (let ix = Math.floor(b.minX / BLOCK_CELL); ix <= Math.floor(b.maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(b.minZ / BLOCK_CELL); iz <= Math.floor(b.maxZ / BLOCK_CELL); iz++) {
      const k = ix * 100000 + iz;
      if (!BLOCK_GRID.has(k)) BLOCK_GRID.set(k, []);
      BLOCK_GRID.get(k).push(b);
    }
  }
}
function pointInPoly(poly, x, z) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const a = poly[i], b = poly[j];
    if ((a.z > z) !== (b.z > z) && x < ((b.x - a.x) * (z - a.z)) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
/** The block (curb island) under (x, z), or null on the roadway */
function blockAt(x, z) {
  const list = BLOCK_GRID.get(Math.floor(x / BLOCK_CELL) * 100000 + Math.floor(z / BLOCK_CELL));
  if (!list) return null;
  for (const b of list) {
    if (x < b.minX || x > b.maxX || z < b.minZ || z > b.maxZ) continue;
    if (b.rect || pointInPoly(b.poly, x, z)) return b;
  }
  return null;
}
/** Blocks whose bounds overlap a rectangle */
function blocksInRect(minX, maxX, minZ, maxZ) {
  const out = new Set();
  for (let ix = Math.floor(minX / BLOCK_CELL); ix <= Math.floor(maxX / BLOCK_CELL); ix++) {
    for (let iz = Math.floor(minZ / BLOCK_CELL); iz <= Math.floor(maxZ / BLOCK_CELL); iz++) {
      const list = BLOCK_GRID.get(ix * 100000 + iz);
      if (list) for (const b of list) if (b.maxX > minX && b.minX < maxX && b.maxZ > minZ && b.minZ < maxZ) out.add(b);
    }
  }
  return [...out];
}

// ---------------------------------------------------------------------------------------------------------------------
// Neighbourhoods for building profiles, labels & the maps
// ---------------------------------------------------------------------------------------------------------------------
// Named places (colonias, barrios), for labels, maps & building profiles
const PLACES = (GEO.places || []).map((p) => ({ name: p.name, x: p.x, z: p.z }));
/** The nearest named place to (x, z) within `radius`, or null */
function placeAt(x, z, radius = 1400) {
  let best = null, bd = radius * radius;
  for (const p of PLACES) {
    const d = (p.x - x) * (p.x - x) + (p.z - z) * (p.z - z);
    if (d < bd) { bd = d; best = p; }
  }
  return best;
}
const CENTRO_RADIUS = 650; // the historic centre around the plaza: denser, taller, commercial ground floors
function districtAt(x, z) {
  if (Math.hypot(x, z) < CENTRO_RADIUS) return 'centro';
  const p = placeAt(x, z, 900);
  if (p && /industrial|parque industrial|ciudad industrial/i.test(p.name)) return 'industrial';
  return 'colonia';
}
for (const b of BLOCKS) b.district = districtAt(b.cx, b.cz);

// ---------------------------------------------------------------------------------------------------------------------
// Landmarks (real footprints from OpenStreetMap: centre, grid-aligned width x depth, height)
// ---------------------------------------------------------------------------------------------------------------------
const LANDMARK_SITES = GEO.landmarks;
// Street-level arrivals shared by every travel mode. Heading 0 faces south (+z), PI north.
const TELEPORT_LOCATIONS = Object.fromEntries(Object.entries(GEO.teleports || {}).map(([k, t]) => [k, { x: t.x, z: t.z, heading: t.heading, name: t.name, sub: t.sub }]));
// Points of interest for the HUD, the maps' pins & search: the teleport spots and the notable places of the city
const POI_KINDS = { monument: 'Monumento', memorial: 'Monumento', artwork: 'Monumento', museum: 'Museo', stadium: 'Estadio', marketplace: 'Mercado',
  bus_station: 'Central', place_of_worship: 'Templo', cathedral: 'Catedral', fountain: 'Fuente', viewpoint: 'Mirador', theatre: 'Teatro', university: 'Universidad', hospital: 'Hospital', park: 'Parque' };
function cityLandmarks() {
  const out = [];
  const seen = new Set();
  const add = (id, name, short, x, z, district) => {
    const key = name.toLowerCase();
    if (seen.has(key) || out.some((o) => Math.hypot(o.x - x, o.z - z) < 40)) return;
    seen.add(key);
    out.push({ id, name, short, x, z, district });
  };
  for (const [id, t] of Object.entries(GEO.teleports || {})) add(id, t.name, t.name.split(' y ')[0].split(' · ')[0], t.x, t.z, t.sub || '');
  const b = CITY.box;
  for (const p of GEO.pois || []) {
    if (!POI_KINDS[p.kind] || (b && (p.x < b.x0 || p.x > b.x1 || p.z < b.z0 || p.z > b.z1))) continue;
    if (p.kind === 'university' || p.kind === 'hospital' || p.kind === 'place_of_worship') continue; // too many to pin
    const place = placeAt(p.x, p.z, 900);
    add(`poi_${out.length}`, p.name, p.name.length > 26 ? `${p.name.slice(0, 24)}…` : p.name, p.x, p.z, place ? place.name : '');
  }
  return out;
}
const CITY_LANDMARKS = cityLandmarks();

const ISLAND_BOUNDS = (() => {
  let minX = Infinity, maxX = -Infinity, minZ = Infinity, maxZ = -Infinity;
  for (const p of CITY_OUTLINE) {
    minX = Math.min(minX, p.x); maxX = Math.max(maxX, p.x); minZ = Math.min(minZ, p.z); maxZ = Math.max(maxZ, p.z);
  }
  return { minX, maxX, minZ, maxZ, sidewalkHeight: 0.22, waterLevel: -2.2 };
})();

/**
 * Exact street / avenue / landmark name at any world (x, z): the nearest roads of the real street centreline
 */
function getLocationLabel(x, z) {
  // "Place · Street & Street": the point of interest or the colonia, over the nearest street corner
  const near = nearestRoads(x, z, 90).filter((r) => r.road.name); // (many streets are unnamed in OpenStreetMap)
  const streets = near.length > 1 && near[1].dist < 40 ? `${near[0].road.name} & ${near[1].road.name}` : near.length ? near[0].road.name : '';
  let place = null;
  for (const lm of CITY_LANDMARKS) if (Math.hypot(x - lm.x, z - lm.z) < 70) { place = lm.name; break; }
  if (!place) {
    const p = placeAt(x, z);
    place = p ? p.name : CITY.city || '';
  }
  if (place && streets) return `${place} · ${streets}`;
  return place || streets || CITY.city || '';
}

// Keyboard shortcuts are ignored while typing into a form field (e.g. the map's street search box)
function isTypingInField(e) {
  return e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'SELECT');
}

// Traffic signal cycle shared by the signal heads (street-details.js) and the traffic (traffic.js), in seconds:
// avenues green until avenueAmber, amber until avenueRed; cross streets green from avenueRed until streetAmber,
// amber until the end of the cycle. Pedestrians cross with the traffic that runs parallel to them, stepping off
// only on the WALK, the first `walk` seconds of its green: long enough before the cross traffic's green for the
// slowest walker to get across the widest avenue.
const SIGNAL_TIMING = { cycle: 60, avenueAmber: 26, avenueRed: 30, streetAmber: 56, walk: 7 };

// 'green', 'amber' or 'red' for avenue or cross street traffic at a given time
function signalPhase(time, isAvenue) {
  const { cycle, avenueAmber, avenueRed, streetAmber } = SIGNAL_TIMING;
  const t = ((time % cycle) + cycle) % cycle;
  if (isAvenue) return t < avenueAmber ? 'green' : t < avenueRed ? 'amber' : 'red';
  return t < avenueRed ? 'red' : t < streetAmber ? 'green' : 'amber';
}

// Do pedestrians walking alongside avenue (or cross street) traffic have the WALK at a given time?
function walkSignal(time, isAvenue) {
  const { cycle, avenueRed, walk } = SIGNAL_TIMING;
  const t = (((time - (isAvenue ? 0 : avenueRed)) % cycle) + cycle) % cycle;
  return t < walk;
}

export {
  CITY,
  PLACES,
  placeAt,
  ALL_AVENUES,
  CENTRAL_PARK_BOUNDS,
  getIslandBoundsAtZ,
  CITY_OUTLINE,
  ALL_STREETS,
  ROADS,
  CITY_LANDMARKS,
  LANDMARK_SITES,
  TELEPORT_LOCATIONS,
  ISLAND_BOUNDS,
  BLOCKS,
  SIGNAL_TIMING,
  streetZ,
  avenueX,
  districtAt,
  blockAt,
  blocksInRect,
  nearestRoads,
  getLocationLabel,
  isTypingInField,
  signalPhase,
  walkSignal
};
